namespace Acme\Module\Kitdemomod\Site\Helper;

defined('_JEXEC') or die;

use Joomla\CMS\Factory;
use Joomla\CMS\Http\HttpFactory;
use Joomla\CMS\Language\Text;
use Joomla\CMS\Plugin\PluginHelper;
use Joomla\CMS\Session\Session;
use Joomla\CMS\Uri\Uri;
use Joomla\Database\DatabaseInterface;

/**
 * Links this site to its owner's account on the store, so paid updates install
 * from Joomla's own update screen:
 *
 *   1. api.register      { installation_id, package_element, domain }
 *   2. api.linkemail     { installation_id, email, email_hash }
 *   3. api.verifyaccess  ?dlid=installation_id:email_hash  → the answer to show
 *   4. the dlid goes onto this extension's own update site, in both
 *      `extra_query` (Joomla appends it to the download) and `location` (the
 *      only channel that reaches the update XML, so the feed can say why an
 *      update would be refused).
 *
 * The link lives in this extension's `custom_data` column in #__extensions, not
 * in its params: saving the Options screen rewrites params, and custom_data is
 * left alone by Joomla's installer, so the link survives both.
 */
final class AccountLinkHelper
{
    /** The store this extension is licensed from. */
    private const STORE_BASE = 'https://store.example.com';

    /** The element of this extension's package in the store. */
    private const PACKAGE_ELEMENT = 'mod_kitdemomod';

    /** The package's Feed Key in the store, when several packages share the element. */
    private const PACKAGE_KEY = '';

    /** The extension whose custom_data holds the link. */
    private const EXT_TYPE = 'module';

    private const EXT_ELEMENT = 'mod_kitdemomod';

    private const EXT_FOLDER = '';

    /** Where the panel posts to, relative to the administrator. Empty: the screen it is on. */
    private const AJAX_URL = '';

    /** Language file and key prefix for the panel's text. */
    private const LANG_EXTENSION = 'mod_kitdemomod.account';

    private const LANG_PREFIX = 'MOD_KITDEMOMOD_ACCOUNT_';

    /** Re-verify at most this often when the panel is opened. */
    private const RECHECK_SECONDS = 86400;

    /** After a failed background recheck, wait this long before trying again. */
    private const RETRY_SECONDS = 3600;

    private const HTTP_TIMEOUT = 15;

    /**
     * One id per request. Without it a register + linkemail pair in one request
     * could generate two different ids, and linkemail would then answer
     * "Installation not found".
     */
    private static ?string $memoInstallationId = null;

    /**
     * The panel, wrapped with what it needs to post back. Echo this wherever the
     * panel should appear.
     */
    public static function render(): string
    {
        self::loadLanguage();

        if (self::EXT_TYPE === 'plugin' && !PluginHelper::isEnabled(self::EXT_FOLDER, self::EXT_ELEMENT)) {
            return '<div class="alert alert-info">' . self::text('PLUGIN_DISABLED') . '</div>';
        }

        try {
            self::refreshIfStale();
        } catch (\Throwable $e) {
            // Housekeeping only; never let it take the settings screen down.
        }

        Factory::getApplication()->getDocument()->getWebAssetManager()
            ->addInlineScript(self::script());

        $endpoint = self::AJAX_URL === '' ? Uri::getInstance()->toString(['path', 'query']) : Uri::base(true) . '/' . self::AJAX_URL;

        return '<div data-csrm-account="' . self::EXT_ELEMENT . '"'
            . ' data-endpoint="' . htmlspecialchars($endpoint, ENT_QUOTES, 'UTF-8') . '"'
            . ' data-token="' . Session::getFormToken() . '"'
            . ' data-failed="' . htmlspecialchars(self::text('LINK_FAILED'), ENT_QUOTES, 'UTF-8', false) . '">'
            . self::panelHtml()
            . '</div>';
    }

    /**
     * Answer one action posted by the panel (link / refresh / unlink), as JSON
     * holding the panel's new HTML.
     */
    public static function handleRequest(): string
    {
        $app = Factory::getApplication();

        self::loadLanguage();

        if (!$app->isClient('administrator') || !Session::checkToken('post')) {
            return json_encode(['error' => Text::_('JINVALID_TOKEN')]);
        }

        if (!self::canManage()) {
            return json_encode(['error' => Text::_('JERROR_ALERTNOAUTHOR')]);
        }

        $notice = '';
        $type   = 'info';

        switch ($app->getInput()->post->getCmd('account_action', '')) {
            case 'link':
                $email = trim((string) $app->getInput()->post->getString('account_email', ''));

                if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
                    $notice = self::text('BAD_EMAIL');
                    $type   = 'warning';
                    break;
                }

                $result = self::link($email);

                if ($result['state'] === 'active') {
                    $notice = Text::sprintf(self::LANG_PREFIX . 'LINKED', $email);
                    $type   = 'success';
                } elseif ($result['message'] !== '') {
                    // Only shown when the panel's own text doesn't already say it.
                    $notice = self::isLinked() ? '' : $result['message'];
                    $type   = 'warning';
                } else {
                    $notice = self::text('LINK_FAILED');
                    $type   = 'warning';
                }

                break;

            case 'refresh':
                $state  = self::refresh();
                $notice = self::text($state === '' ? 'NOT_LINKED' : 'REFRESHED_' . strtoupper($state));
                $type   = $state === 'active' ? 'success' : 'info';
                break;

            case 'unlink':
                self::unlink();
                $notice = self::text('UNLINKED');
                break;

            default:
                return json_encode(['error' => Text::_('JERROR_ALERTNOAUTHOR')]);
        }

        return json_encode(['html' => self::panelHtml($notice, $type)]);
    }

    /** Tells whoever just installed this where to link, unless the site already is. */
    public static function noticeOnInstall(): void
    {
        self::loadLanguage();

        if (!self::isLinked()) {
            Factory::getApplication()->enqueueMessage(self::text('INSTALL_NOTICE'), 'info');
        }
    }

    /**
     * Put the dlid on this extension's own update site. Joomla rebuilds that row
     * when the extension updates, so your script.php postflight schedules this
     * for the end of the request (see the kit's snippets/postflight.php).
     *
     * Only the update site for this package on the store itself is touched.
     * Other extensions on the same site have their own update sites and keys.
     *
     * When the site is not linked nothing is written. Unlink passes the dlid it
     * is dropping as $forget, and only that one is taken off.
     *
     * @return int Rows written.
     */
    public static function syncUpdateSite(string $forget = ''): int
    {
        $dlid    = self::getDlid();
        $written = 0;

        if ($dlid === '' && $forget === '') {
            return 0;
        }

        $extraQuery = $dlid === '' ? '' : 'dlid=' . $dlid;

        try {
            $db   = Factory::getContainer()->get(DatabaseInterface::class);
            $rows = $db->setQuery(
                $db->getQuery(true)
                    ->select($db->quoteName(['update_site_id', 'location', 'extra_query']))
                    ->from($db->quoteName('#__update_sites'))
                    ->where($db->quoteName('location') . ' LIKE ' . $db->quote('%element=' . self::PACKAGE_ELEMENT . '%'))
            )->loadAssocList() ?: [];

            foreach ($rows as $row) {
                if (!self::isOwnFeed((string) $row['location'])) {
                    continue;
                }

                // Unlinking: leave a dlid that isn't the one being forgotten.
                if ($dlid === '' && (string) $row['extra_query'] !== '' && (string) $row['extra_query'] !== 'dlid=' . $forget) {
                    $extraQuery = (string) $row['extra_query'];
                } elseif ($dlid === '') {
                    $extraQuery = '';
                }

                $location = rtrim((string) preg_replace('/([?&])dlid=[^&]*/', '', (string) $row['location']), '?&');

                if ($dlid !== '') {
                    $location .= (str_contains($location, '?') ? '&' : '?') . 'dlid=' . $dlid;
                }

                if ($location === (string) $row['location'] && (string) $row['extra_query'] === $extraQuery) {
                    continue;
                }

                $db->setQuery(
                    $db->getQuery(true)
                        ->update($db->quoteName('#__update_sites'))
                        ->set($db->quoteName('extra_query') . ' = ' . $db->quote($extraQuery))
                        ->set($db->quoteName('location') . ' = ' . $db->quote($location))
                        ->where($db->quoteName('update_site_id') . ' = ' . (int) $row['update_site_id'])
                )->execute();

                $written++;
            }
        } catch (\Throwable $e) {
            // Bookkeeping only; never let it break an install or the panel.
        }

        return $written;
    }

    /**
     * The stored link.
     *
     * @return array{installation_id:string,email:string,email_hash:string,status:string,message:string,
     *               renewal_url:string,signup_url:string,package_title:string,last_verified:int,last_attempt:int}
     */
    public static function read(): array
    {
        $data = self::readAll();

        return [
            'installation_id' => (string) ($data['installation_id'] ?? ''),
            'email'           => (string) ($data['email'] ?? ''),
            'email_hash'      => (string) ($data['email_hash'] ?? ''),
            'status'          => (string) ($data['status'] ?? ''),
            'message'         => (string) ($data['message'] ?? ''),
            'renewal_url'     => (string) ($data['renewal_url'] ?? ''),
            'signup_url'      => (string) ($data['signup_url'] ?? ''),
            'package_title'   => (string) ($data['package_title'] ?? ''),
            'last_verified'   => (int) ($data['last_verified'] ?? 0),
            'last_attempt'    => (int) ($data['last_attempt'] ?? 0),
        ];
    }

    /** True once an email has been linked, whatever the store said about it. */
    public static function isLinked(): bool
    {
        $account = self::read();

        return $account['installation_id'] !== '' && $account['email_hash'] !== '';
    }

    /**
     * "installation_id:email_hash", or '' when not linked or malformed. Anything
     * that isn't a well-formed id and hash never reaches the update site's URL.
     */
    public static function getDlid(): string
    {
        $account = self::read();
        $dlid    = $account['installation_id'] . ':' . $account['email_hash'];

        return preg_match('/^\d{14}_[a-z0-9.-]{1,68}_[0-9a-f]{6,32}:[0-9a-f]{64}$/D', $dlid) ? $dlid : '';
    }

    /** Who may link and unlink: whoever can change this extension's settings. */
    public static function canManage(): bool
    {
        $user = Factory::getApplication()->getIdentity();

        // com_ajax has no permission gate of its own, so a plugin needs what the
        // Plugins screen itself asks for. A module's panel is on the Modules screen.
        return match (self::EXT_TYPE) {
            'plugin' => $user->authorise('core.manage', 'com_plugins') && $user->authorise('core.edit', 'com_plugins'),
            'module' => $user->authorise('core.manage', 'com_modules') && $user->authorise('core.edit', 'com_modules'),
            default  => $user->authorise('core.admin', self::EXT_ELEMENT),
        };
    }

    /**
     * Register this site and link it to $email, then ask the store what that
     * account is entitled to.
     *
     * @return array{state:string,message:string}
     *         state is active / lapsed / not_a_member / blacklisted / over_limit
     *         / denied (anything else, including network failures).
     */
    private static function link(string $email): array
    {
        $email = strtolower(trim($email));

        $register = self::register();

        if (!$register['ok']) {
            return ['state' => 'denied', 'message' => $register['error']];
        }

        $emailHash = hash('sha256', $email);
        $link      = self::post('api.linkemail', [
            'installation_id' => self::ensureInstallationId(),
            'email_hash'      => $emailHash,
            'email'           => $email,
        ]);

        // Over the site limit is an answer, not a failure: the store has parked
        // the address and verifyaccess will explain.
        if (!$link['ok'] && ($link['payload']['access_state'] ?? '') !== 'over_limit') {
            return ['state' => 'denied', 'message' => $link['error']];
        }

        // The email is saved whatever the verdict, so the panel can show which
        // address was tried. Only Unlink clears it.
        self::saveAll(['email' => $email, 'email_hash' => $emailHash]);

        $result = self::verifyAndStore($emailHash);

        return ['state' => $result['state'], 'message' => $result['message']];
    }

    /** Re-ask the store now, ignoring the daily throttle. Returns the new state, or '' when not linked. */
    private static function refresh(): string
    {
        $account = self::read();

        if ($account['installation_id'] === '' || $account['email_hash'] === '') {
            return '';
        }

        return self::verifyAndStore($account['email_hash'])['state'];
    }

    /**
     * Panel-load housekeeping: stamp the dlid onto the update site, then
     * re-verify if the last answer is more than a day old. Silent on failure; a
     * network blip must not change what the panel shows.
     */
    private static function refreshIfStale(): void
    {
        self::syncUpdateSite();

        $account = self::read();

        if ($account['installation_id'] === '' || $account['email_hash'] === '') {
            return;
        }

        if ($account['last_verified'] > 0 && (time() - $account['last_verified']) < self::RECHECK_SECONDS) {
            return;
        }

        // The store was unreachable recently. Without this, every panel load
        // would sit through the full HTTP timeout until it came back.
        if ($account['last_attempt'] > 0 && (time() - $account['last_attempt']) < self::RETRY_SECONDS) {
            return;
        }

        self::verifyAndStore($account['email_hash'], true);
    }

    /**
     * Forget the link on this site and take the dlid off the update site. The
     * store keeps its installation row; the next link generates a fresh id.
     */
    private static function unlink(): void
    {
        $old = self::getDlid();

        self::clearAll();
        self::$memoInstallationId = null;
        self::syncUpdateSite($old);
    }

    /**
     * True only for an update-XML URL for this package on the store itself.
     *
     * Only "&amp;" is decoded (manifests write the query that way). A full
     * html_entity_decode() would also turn "&sol;" or "&commat;" into "/" and
     * "@", so the string checked here would name a different host from the one
     * Joomla actually requests, with the dlid attached.
     */
    private static function isOwnFeed(string $url): bool
    {
        $parts = parse_url(str_replace('&amp;', '&', $url));
        $store = parse_url(self::STORE_BASE);

        if (!is_array($parts) || !is_array($store) || isset($parts['user']) || isset($parts['pass'])) {
            return false;
        }

        if (
            strtolower((string) ($parts['scheme'] ?? '')) !== strtolower((string) ($store['scheme'] ?? ''))
            || ($parts['port'] ?? null) !== ($store['port'] ?? null)
        ) {
            return false;
        }

        $bare = preg_replace('/^www\./', '', strtolower((string) ($store['host'] ?? '')));

        if (!in_array(strtolower((string) ($parts['host'] ?? '')), [$bare, 'www.' . $bare], true)) {
            return false;
        }

        parse_str((string) ($parts['query'] ?? ''), $query);

        return ($query['option'] ?? '') === 'com_csreleasemanager'
            && ($query['task'] ?? '') === 'api.updatexml'
            && ($query['element'] ?? '') === self::PACKAGE_ELEMENT
            && (self::PACKAGE_KEY === '' || ($query['package'] ?? '') === self::PACKAGE_KEY);
    }

    /**
     * Step 1. Idempotent on the store: a known id answers already_registered.
     *
     * @return array{ok:bool,error:string}
     */
    private static function register(): array
    {
        try {
            $installationId = self::ensureInstallationId();
        } catch (\RuntimeException $e) {
            return ['ok' => false, 'error' => $e->getMessage()];
        }

        $body = [
            'installation_id' => $installationId,
            'package_element' => self::PACKAGE_ELEMENT,
            'domain'          => (string) (parse_url((string) Uri::root(), PHP_URL_HOST) ?: ''),
        ];

        if (self::PACKAGE_KEY !== '') {
            $body['package_key'] = self::PACKAGE_KEY;
        }

        $result = self::post('api.register', $body);

        if ($result['ok'] && self::read()['installation_id'] !== $installationId) {
            // Saved only now that the store has a row for it. Saving at
            // generation time would leave sites holding ids the store never accepted.
            self::saveAll(['installation_id' => $installationId]);
        }

        return ['ok' => $result['ok'], 'error' => $result['error']];
    }

    /**
     * Steps 3 and 4: ask the store, store the answer, stamp the update site.
     *
     * With $keepOnFailure (the background recheck), a network or server error
     * leaves the previous answer in place instead of overwriting it.
     *
     * @return array{state:string,message:string}
     */
    private static function verifyAndStore(string $emailHash, bool $keepOnFailure = false): array
    {
        $result = self::verify($emailHash);

        if ($keepOnFailure && $result['transport_error']) {
            self::saveAll(['last_attempt' => time()]);

            return ['state' => self::read()['status'], 'message' => self::read()['message']];
        }

        self::saveAll([
            'status'        => $result['state'],
            'message'       => $result['message'],
            'renewal_url'   => $result['renewal_url'],
            'signup_url'    => $result['signup_url'],
            'package_title' => $result['package_title'],
            'last_verified' => time(),
        ]);

        self::syncUpdateSite();

        return ['state' => $result['state'], 'message' => $result['message']];
    }

    /**
     * @return array{state:string,message:string,renewal_url:string,signup_url:string,
     *               package_title:string,transport_error:bool}
     */
    private static function verify(string $emailHash, bool $healed = false): array
    {
        $denied = static fn (string $message, bool $transport = false): array => [
            'state'           => 'denied',
            'message'         => $message,
            'renewal_url'     => '',
            'signup_url'      => '',
            'package_title'   => '',
            'transport_error' => $transport,
        ];

        try {
            $dlid = self::ensureInstallationId() . ':' . $emailHash;
        } catch (\RuntimeException $e) {
            return $denied($e->getMessage());
        }

        try {
            $response = HttpFactory::getHttp()->get(
                self::endpoint('api.verifyaccess') . '&dlid=' . rawurlencode($dlid),
                ['Accept' => 'application/json'],
                self::HTTP_TIMEOUT
            );
        } catch (\Throwable $e) {
            return $denied('Could not reach ' . self::STORE_BASE . ': ' . $e->getMessage(), true);
        }

        $payload = json_decode((string) $response->body, true);

        if (!is_array($payload) || empty($payload['state'])) {
            return $denied('The store sent an unexpected answer (HTTP ' . (int) $response->code . ').', true);
        }

        $state = (string) $payload['state'];

        // The store has no row for an id this site already holds: register the
        // same id again, re-link the saved email, and ask once more.
        if ($state === 'installation_not_found' && !$healed && self::heal($emailHash)) {
            return self::verify($emailHash, true);
        }

        if (!in_array($state, ['active', 'lapsed', 'not_a_member', 'blacklisted', 'over_limit'], true)) {
            $state = 'denied';
        }

        // Capped because they are stored in a text column: an oversized answer
        // from a compromised store must not be able to break the save.
        return [
            'state'           => $state,
            'message'         => mb_substr((string) ($payload['message'] ?? ''), 0, 1000),
            'renewal_url'     => mb_substr((string) ($payload['renewal_url'] ?? ''), 0, 2048),
            'signup_url'      => mb_substr((string) ($payload['signup_url'] ?? ''), 0, 2048),
            'package_title'   => mb_substr((string) ($payload['package_title'] ?? ''), 0, 255),
            'transport_error' => false,
        ];
    }

    /** Re-register the saved id and re-link the saved email, if they match $emailHash. */
    private static function heal(string $emailHash): bool
    {
        $account = self::read();
        $email   = strtolower(trim($account['email']));

        if ($account['installation_id'] === '' || $email === '' || !hash_equals(hash('sha256', $email), $emailHash)) {
            return false;
        }

        if (!self::register()['ok']) {
            return false;
        }

        return self::post('api.linkemail', [
            'installation_id' => $account['installation_id'],
            'email_hash'      => $emailHash,
            'email'           => $email,
        ])['ok'];
    }

    /**
     * The saved id, or a new "YmdHis_host_xxxxxx" one (memoised, not saved;
     * register() saves it once the store accepts it).
     *
     * @throws \RuntimeException under CLI, where there is no host to put in the id.
     */
    private static function ensureInstallationId(): string
    {
        if (self::$memoInstallationId !== null && self::$memoInstallationId !== '') {
            return self::$memoInstallationId;
        }

        $saved = self::read()['installation_id'];

        if ($saved !== '') {
            return self::$memoInstallationId = $saved;
        }

        $host = strtolower((string) (parse_url((string) Uri::root(), PHP_URL_HOST) ?: ''));

        if ($host === '') {
            throw new \RuntimeException('This site has no host name here. Link the account from your browser.');
        }

        // 64 random bits: the timestamp and host are guessable and sha256(email)
        // is public to anyone who knows the address, so this is the dlid's only
        // secret. The host is capped so the id stays inside the store's 100
        // characters (14 + 1 + 68 + 1 + 16).
        return self::$memoInstallationId = date('YmdHis') . '_' . substr($host, 0, 68) . '_' . bin2hex(random_bytes(8));
    }

    /**
     * POST JSON to a store task.
     *
     * @return array{ok:bool,error:string,payload:array}
     */
    private static function post(string $task, array $body): array
    {
        try {
            $response = HttpFactory::getHttp()->post(
                self::endpoint($task),
                json_encode($body, JSON_UNESCAPED_SLASHES),
                ['Content-Type' => 'application/json', 'Accept' => 'application/json'],
                self::HTTP_TIMEOUT
            );
        } catch (\Throwable $e) {
            return ['ok' => false, 'error' => 'Could not reach ' . self::STORE_BASE . ': ' . $e->getMessage(), 'payload' => []];
        }

        $code    = (int) $response->code;
        $payload = json_decode((string) $response->body, true);
        $payload = is_array($payload) ? $payload : [];

        if ($code === 200 || $code === 201) {
            return ['ok' => true, 'error' => '', 'payload' => $payload];
        }

        return [
            'ok'      => false,
            'error'   => (string) (($payload['error'] ?? $payload['message'] ?? '') ?: 'HTTP ' . $code),
            'payload' => $payload,
        ];
    }

    private static function endpoint(string $task): string
    {
        return self::STORE_BASE . '/index.php?option=com_csreleasemanager&task=' . $task . '&format=json';
    }

    /** The panel's HTML. Every store-supplied value is escaped in the template. */
    private static function panelHtml(string $notice = '', string $noticeType = 'info'): string
    {
        $account   = self::read();
        $canManage = self::canManage();
        $text      = static fn (string $key): string => self::text($key);

        ob_start();
        include __DIR__ . '/account-panel.php';

        return (string) ob_get_clean();
    }

    private static function text(string $key): string
    {
        return Text::_(self::LANG_PREFIX . $key);
    }

    private static function loadLanguage(): void
    {
        Factory::getApplication()->getLanguage()->load(self::LANG_EXTENSION, JPATH_SITE . '/modules/mod_kitdemomod');
    }

    /** The panel posts with fetch, so it works inside another form such as a plugin's edit screen. */
    private static function script(): string
    {
        $selector = '[data-csrm-account="' . self::EXT_ELEMENT . '"]';

        return <<<JS
(function () {
    var selector = '{$selector}';

    function send(box, action) {
        var body  = new FormData();
        var input = box.querySelector('input[name="account_email"]');
        var error = box.querySelector('[data-account-error]');

        body.append('account_action', action);
        body.append(box.dataset.token, '1');

        if (input) {
            body.append('account_email', input.value);
        }

        box.querySelectorAll('button').forEach(function (button) { button.disabled = true; });

        fetch(box.dataset.endpoint, {method: 'POST', body: body, credentials: 'same-origin'})
            .then(function (response) { return response.text(); })
            .then(function (text) {
                var data = null;

                try { data = JSON.parse(text); } catch (e) { data = null; }

                if (data && data.html) {
                    box.innerHTML = data.html;
                    return;
                }

                throw new Error(data && data.error ? data.error : box.dataset.failed);
            })
            .catch(function (e) {
                box.querySelectorAll('button').forEach(function (button) { button.disabled = false; });

                if (error) {
                    error.textContent = e.message;
                    error.classList.remove('d-none');
                }
            });
    }

    document.addEventListener('click', function (event) {
        var button = event.target.closest(selector + ' [data-account-action]');

        if (button) {
            event.preventDefault();
            send(button.closest(selector), button.dataset.accountAction);
        }
    });

    document.addEventListener('keydown', function (event) {
        if (event.key === 'Enter' && event.target.matches(selector + ' input[name="account_email"]')) {
            event.preventDefault();
            send(event.target.closest(selector), 'link');
        }
    });
})();
JS;
    }

    /** This extension's row, as a query condition. */
    private static function whereExtension($query, $db)
    {
        $query->where($db->quoteName('type') . ' = ' . $db->quote(self::EXT_TYPE))
            ->where($db->quoteName('element') . ' = ' . $db->quote(self::EXT_ELEMENT));

        if (self::EXT_FOLDER !== '') {
            $query->where($db->quoteName('folder') . ' = ' . $db->quote(self::EXT_FOLDER));
        }

        return $query;
    }

    /** The whole custom_data column, straight from the database. */
    private static function readColumn(): array
    {
        try {
            $db  = Factory::getContainer()->get(DatabaseInterface::class);
            $raw = (string) $db->setQuery(
                self::whereExtension($db->getQuery(true)->select($db->quoteName('custom_data'))->from($db->quoteName('#__extensions')), $db)
            )->loadResult();
        } catch (\Throwable $e) {
            return [];
        }

        $column = json_decode($raw, true);

        return is_array($column) ? $column : [];
    }

    private static function readAll(): array
    {
        $column = self::readColumn();

        return is_array($column['csrm_account'] ?? null) ? $column['csrm_account'] : [];
    }

    private static function writeColumn(array $column): void
    {
        $db = Factory::getContainer()->get(DatabaseInterface::class);

        $db->setQuery(
            self::whereExtension(
                $db->getQuery(true)
                    ->update($db->quoteName('#__extensions'))
                    ->set($db->quoteName('custom_data') . ' = ' . $db->quote($column === [] ? '' : json_encode($column, JSON_UNESCAPED_SLASHES))),
                $db
            )
        )->execute();
    }

    /** Merge values into the link. */
    private static function saveAll(array $values): void
    {
        $column                 = self::readColumn();
        $column['csrm_account'] = array_merge(self::readAll(), $values);

        self::writeColumn($column);
    }

    private static function clearAll(): void
    {
        $column = self::readColumn();
        unset($column['csrm_account']);

        self::writeColumn($column);
    }
}
